template.schema:
/** A node in the rendered page tree. */
type PageNode =
  | {
      kind: "heading";
      level: "h1" | "h2" | "h3";
      text: string;
    }
  | {
      kind: "paragraph";
      text: string;
    }
  | {
      kind: "button";
      label: string;
      /** Destination URL or action target. */
      url: string;
    }
  | {
      kind: "section";
      title?: string;
      children: PageNode[];
    };

interface Input {
  /** The topic or purpose of the page to generate. */
  topic: string;
  /** Key points or content sections to include in the layout. */
  keyPoints: string[];
}

type Output = PageNode;
